"use client";
import React, { useState } from 'react';

// Type for customer
interface Customer {
  name: string;
  phone: string;
  district: string;
  loanAmount: number;
  dueDate: string;
  overdue: boolean;
  balance: number;
  selfie: string;  // Store the selfie image URL here
}

// LoanTracker component
const LoanTracker = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [district, setDistrict] = useState('');
  const [loanAmount, setLoanAmount] = useState(0);
  const [dueDate, setDueDate] = useState('');
  const [paymentAmount, setPaymentAmount] = useState(0);
  const [selfie, setSelfie] = useState<string>(''); // For storing selfie URL
  
  const calculateOverdueStatus = (dueDate: string): boolean => {
    const due = new Date(dueDate);
    const today = new Date();
    return today > due;
  };

  // Handle form submission for new customers
  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    // Calculate overdue status based on due date
    const overdueStatus = calculateOverdueStatus(dueDate);

    const newCustomer: Customer = {
      name,
      phone,
      district,
      loanAmount,
      dueDate,
      overdue: overdueStatus,
      balance: loanAmount, // Initial balance is the loan amount
      selfie, // Store the selfie image URL
    };

    setCustomers([...customers, newCustomer]);

    // Clear form fields after submitting
    setName('');
    setPhone('');
    setDistrict('');
    setLoanAmount(0);
    setDueDate('');
    setSelfie('');
  };

  // Handle payment submission
  const handlePayment = (index: number) => {
    const newCustomers = [...customers];
    const customer = newCustomers[index];
    
    if (paymentAmount > 0 && paymentAmount <= customer.balance) {
      customer.balance -= paymentAmount;
      setCustomers(newCustomers);
      setPaymentAmount(0);
    } else {
      alert('Invalid payment amount!');
    }
  };

  // Generate the printable receipt
  const printReceipt = (customer: Customer) => {
    const receiptContent = `
      <div style="text-align: center; font-family: Arial, sans-serif; padding: 20px;">
        <h2>Loan Payment Receipt</h2>
        <p><strong>Customer Name:</strong> ${customer.name}</p>
        <p><strong>Phone Number:</strong> ${customer.phone}</p>
        <p><strong>District:</strong> ${customer.district}</p>
        <p><strong>Loan Amount:</strong> KSH ${customer.loanAmount}</p>
        <p><strong>Amount Paid:</strong> KSH ${customer.loanAmount - customer.balance}</p>
        <p><strong>Remaining Balance:</strong> KSH ${customer.balance}</p>
        <p><strong>Due Date:</strong> ${new Date(customer.dueDate).toLocaleDateString()}</p>
        <p><strong>Date:</strong> ${new Date().toLocaleDateString()}</p>
        <p style="color: ${customer.overdue ? 'red' : 'green'}"><strong>Status:</strong> ${customer.overdue ? 'Overdue' : 'Paid On Time'}</p>
      </div>
    `;
    
    const printWindow = window.open('', '', 'width=600,height=600');
    printWindow?.document.write(receiptContent);
    printWindow?.document.close();
    printWindow?.print();
  };

  // Handle selfie upload
  const handleSelfieChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelfie(reader.result as string); // Set selfie URL
      };
      reader.readAsDataURL(file); // Convert the file to data URL
    }
  };

  return (
    <div className="p-6 max-w-screen-md mx-auto">
      <h1 className="text-4xl font-semibold mb-6 text-center text-blue-600">Loan Tracker</h1>

      {/* Form to add customer details */}
      <form onSubmit={handleSubmit} className="bg-white p-6 shadow-lg rounded-md mb-6">
        <div className="mb-4">
          <label htmlFor="name" className="block text-sm font-medium text-gray-700">Customer Name</label>
          <input
            type="text"
            id="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-3"
            required
          />
        </div>

        <div className="mb-4">
          <label htmlFor="phone" className="block text-sm font-medium text-gray-700">Phone Number</label>
          <input
            type="tel"
            id="phone"
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-3"
            required
          />
        </div>

        <div className="mb-4">
          <label htmlFor="district" className="block text-sm font-medium text-gray-700">District</label>
          <input
            type="text"
            id="district"
            value={district}
            onChange={(e) => setDistrict(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-3"
            required
          />
        </div>

        <div className="mb-4">
          <label htmlFor="loanAmount" className="block text-sm font-medium text-gray-700">Loan Amount (KSH)</label>
          <input
            type="number"
            id="loanAmount"
            value={loanAmount}
            onChange={(e) => setLoanAmount(Number(e.target.value))}
            className="mt-1 block w-full border border-gray-300 rounded-md p-3"
            required
          />
        </div>

        <div className="mb-4">
          <label htmlFor="dueDate" className="block text-sm font-medium text-gray-700">Due Date</label>
          <input
            type="date"
            id="dueDate"
            value={dueDate}
            onChange={(e) => setDueDate(e.target.value)}
            className="mt-1 block w-full border border-gray-300 rounded-md p-3"
            required
          />
        </div>

        {/* Selfie Upload */}
        <div className="mb-4">
          <label htmlFor="selfie" className="block text-sm font-medium text-gray-700">Upload Selfie</label>
          <input
            type="file"
            id="selfie"
            onChange={handleSelfieChange}
            accept="image/*"
            className="mt-1 block w-full border border-gray-300 rounded-md p-3"
          />
        </div>

        <button
          type="submit"
          className="bg-blue-500 text-white py-3 px-6 rounded-md w-full"
        >
          Add Customer
        </button>
      </form>

      {/* Display the list of customers */}
      <h2 className="text-2xl font-semibold mb-4 text-center">Customers List</h2>
      <div className="bg-white shadow-md rounded-md p-6">
        {customers.length === 0 ? (
          <p className="text-center text-gray-500">No customers added yet.</p>
        ) : (
          <ul className="space-y-6">
            {customers.map((customer, index) => (
              <li key={index} className="flex justify-between items-center border-b py-4">
                <div className="flex flex-col">
                  <div className="flex items-center mb-2">
                    {/* Display Selfie */}
                    <img
                      src={customer.selfie || '/placeholder.jpg'} // Use a placeholder image if no selfie
                      alt="Selfie"
                      className="w-12 h-12 rounded-full mr-4"
                    />
                    <div>
                      <p><strong>Name:</strong> {customer.name}</p>
                      <p><strong>Phone:</strong> {customer.phone}</p>
                      <p><strong>District:</strong> {customer.district}</p>
                      <p><strong>Loan Amount:</strong> KSH {customer.loanAmount}</p>
                      <p><strong>Remaining Balance:</strong> KSH {customer.balance}</p>
                      <p><strong>Due Date:</strong> {new Date(customer.dueDate).toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>

                {/* Payment Section */}
                <div className="flex flex-col items-end">
                  <input
                    type="number"
                    placeholder="Payment Amount (KSH)"
                    value={paymentAmount}
                    onChange={(e) => setPaymentAmount(Number(e.target.value))}
                    className="border p-3 mb-2 rounded-md w-full"
                  />
                  <button
                    onClick={() => handlePayment(index)}
                    className="bg-green-500 text-white py-2 px-4 rounded-md mb-2 w-full"
                  >
                    Make Payment
                  </button>
                  <button
                    onClick={() => printReceipt(customer)}
                    className="bg-blue-500 text-white py-2 px-4 rounded-md w-full"
                  >
                    Print Receipt
                  </button>
                </div>

                <span className={`text-sm font-bold ${customer.overdue ? 'text-red-600' : 'text-green-600'}`}>
                  {customer.overdue ? 'Overdue' : 'Paid On Time'}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default LoanTracker;
